const require_index = require("../useCustomCompareEffect/index.js");
let lodash_es = require("lodash-es");
//#region src/useDeepCompareEffect/index.ts
const useDeepCompareEffect = (effect, deps) => {
	if (process.env.NODE_ENV !== "production") {
		if (!Array.isArray(deps) || !deps.length) console.warn("`useDeepCompareEffect` should not be used with no dependencies. Use React.useEffect instead.");
	}
	require_index.useCustomCompareEffect(effect, deps, lodash_es.isEqual);
};
//#endregion
exports.useDeepCompareEffect = useDeepCompareEffect;
